using MassageShop.API.Data;using MassageShop.API.Helpers;using MassageShop.API.Models.Entities;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace MassageShop.API.Controllers{[ApiController][Route("api/attendance-monthly")][Authorize(Roles="ADMIN")]public class AttendanceMonthlyController:ControllerBase{readonly AppDbContext db;public AttendanceMonthlyController(AppDbContext d)=>db=d;async Task<List<AttendanceMonthlySummary>> Build(int y,int m){var from=new DateTime(y,m,1);var to=from.AddMonths(1);var emps=await db.Employees.Include(x=>x.User).Where(x=>x.IsActive).ToListAsync();var shifts=await db.WorkShifts.Where(x=>x.WorkDate>=from&&x.WorkDate<to).ToListAsync();var atts=await db.Attendances.Include(x=>x.WorkShift).Where(x=>x.WorkShift.WorkDate>=from&&x.WorkShift.WorkDate<to).ToListAsync();return emps.Select(e=>{var ss=shifts.Where(s=>s.EmployeeId==e.Id&&s.ShiftType!="OFF").ToList();var aa=atts.Where(a=>a.EmployeeId==e.Id).ToList();return new AttendanceMonthlySummary{EmployeeId=e.Id,Year=y,Month=m,AssignedShiftCount=ss.Count,WorkedDayCount=aa.Count(a=>a.CheckInAt!=null),WorkedMinutes=aa.Sum(a=>a.WorkedMinutes),LateCount=aa.Count(a=>a.LateMinutes>0),LateMinutes=aa.Sum(a=>a.LateMinutes),EarlyLeaveCount=aa.Count(a=>a.EarlyLeaveMinutes>0),EarlyLeaveMinutes=aa.Sum(a=>a.EarlyLeaveMinutes),AbsentCount=ss.Count(s=>s.EndTime<=DateTime.UtcNow.TimeOfDay&&s.WorkDate.Date<DateTime.UtcNow.Date&&!aa.Any(a=>a.WorkShiftId==s.Id)),LeaveCount=aa.Count(a=>a.Status=="ON_LEAVE"),OvertimeMinutes=0,Status="OPEN"};}).ToList();}[HttpGet]public async Task<IActionResult>Get(int year,int month){var saved=await db.AttendanceMonthlySummaries.Include(x=>x.Employee).ThenInclude(x=>x.User).Where(x=>x.Year==year&&x.Month==month).ToListAsync();if(saved.Any())return Ok(saved);return Ok(await Build(year,month));}[HttpPost("close")]public async Task<IActionResult>Close(int year,int month){if(await db.AttendanceMonthlySummaries.AnyAsync(x=>x.Year==year&&x.Month==month&&x.Status=="CLOSED"))return BadRequest(new{message="Bảng công tháng đã chốt"});var rows=await Build(year,month);foreach(var x in rows){x.Status="CLOSED";x.ClosedAt=DateTime.UtcNow;x.ClosedByUserId=User.GetUserId();}db.AttendanceMonthlySummaries.AddRange(rows);await db.SaveChangesAsync();return Ok(rows);}[HttpPost("manual")]public async Task<IActionResult>Manual(int attendanceId,string reason,DateTime? checkIn,DateTime? checkOut){var a=await db.Attendances.FindAsync(attendanceId);if(a==null)return NotFound();var s=await db.AttendanceMonthlySummaries.FirstOrDefaultAsync(x=>x.EmployeeId==a.EmployeeId&&x.Year==DateTime.UtcNow.Year&&x.Month==DateTime.UtcNow.Month&&x.Status=="CLOSED");if(s!=null)return BadRequest(new{message="Bảng công tháng đã chốt"});a.CheckInAt=checkIn??a.CheckInAt;a.CheckOutAt=checkOut??a.CheckOutAt;a.ManualNote=reason;await db.SaveChangesAsync();return Ok(a);}}}
